            """\
            python3 - <<'PY'
            import json
            import math
            from pathlib import Path

            PARAMS = json.loads(__PARAMS_JSON__)

            def add_check(checks, name, passed, observed=None, expected=None, note=None):
                checks.append({
                    "name": name,
                    "passed": bool(passed),
                    "observed": observed,
                    "expected": expected,
                    "note": note,
                })

            try:
                from PIL import Image, ImageChops, ImageStat
            except ImportError:
                print(json.dumps({"error": "Pillow is not installed in the guest runtime"}, ensure_ascii=False))
                raise SystemExit(0)

            def open_rgb(path):
                img = Image.open(path)
                fmt = img.format
                img = img.convert("RGB")
                return img, fmt

            def rmsdiff(a, b):
                if a.size != b.size:
                    b = b.resize(a.size)
                diff = ImageChops.difference(a, b)
                stat = ImageStat.Stat(diff)
                return math.sqrt(sum(value * value for value in stat.rms) / len(stat.rms))

            def crop_box(img, box_spec):
                w, h = img.size
                left = int(round(float(box_spec.get("left", 0)) * w))
                top = int(round(float(box_spec.get("top", 0)) * h))
                right = int(round(float(box_spec.get("right", 1)) * w))
                bottom = int(round(float(box_spec.get("bottom", 1)) * h))
                left = max(0, min(w - 1, left))
                top = max(0, min(h - 1, top))
                right = max(left + 1, min(w, right))
                bottom = max(top + 1, min(h, bottom))
                return (left, top, right, bottom)

            checks = []
            evidence = {
                "downloads_dir": PARAMS.get("downloads_dir"),
                "manual_trajectory_checks": PARAMS.get("manual_trajectory_checks") or [],
                "data_source_priority": "downloaded image files first; source attachment images second; trajectory/screenshot only for unpersisted brush click placement",
            }
            min_whole_rms = float(PARAMS.get("min_whole_image_rms_diff", 4.0))
            max_marker_rms = float(PARAMS.get("max_rgb_marker_rms_diff", 6.0))
            marker_box = PARAMS.get("rgb_marker_box") or {"left": 0.87, "top": 0.02, "right": 0.99, "bottom": 0.13}

            artifacts = []
            for item in PARAMS.get("expected_exports") or []:
                label = str(item.get("label") or "")
                source_path = Path(str(item.get("source_path") or ""))
                output_path = Path(str(item.get("output_path") or ""))
                artifact = {"label": label, "source_path": str(source_path), "output_path": str(output_path)}

                add_check(checks, f"{label}:source_exists", source_path.is_file(), str(source_path), "source attachment image exists")
                add_check(checks, f"{label}:output_exists", output_path.is_file(), str(output_path), "downloaded edited image exists")
                if not source_path.is_file() or not output_path.is_file():
                    artifacts.append(artifact)
                    continue

                try:
                    src, src_fmt = open_rgb(source_path)
                    out, out_fmt = open_rgb(output_path)
                    artifact.update({
                        "source_format": src_fmt,
                        "output_format": out_fmt,
                        "source_size": list(src.size),
                        "output_size": list(out.size),
                        "output_bytes": output_path.stat().st_size,
                    })
                except Exception as exc:
                    add_check(checks, f"{label}:image_readable", False, str(exc), "readable image")
                    artifacts.append(artifact)
                    continue

                add_check(checks, f"{label}:image_readable", True, artifact, "readable image")
                add_check(checks, f"{label}:format_jpeg", str(out_fmt or "").upper() in {"JPEG", "JPG"}, out_fmt, "JPEG/JPG")
                add_check(checks, f"{label}:nonempty_file", artifact["output_bytes"] > 1024, artifact["output_bytes"], ">1024 bytes")
                add_check(checks, f"{label}:same_dimensions_as_source", out.size == src.size, {"source": list(src.size), "output": list(out.size)}, "same width and height")

                whole_rms = rmsdiff(src, out)
                marker = crop_box(src, marker_box)
                marker_rms = rmsdiff(src.crop(marker), out.crop(marker))
                artifact["whole_image_rms_diff"] = whole_rms
                artifact["rgb_marker_rms_diff"] = marker_rms
                artifact["rgb_marker_box_px"] = marker
                add_check(checks, f"{label}:edited_not_identical_to_source", whole_rms >= min_whole_rms, whole_rms, f">= {min_whole_rms}")
                add_check(checks, f"{label}:rgb_marker_preserved", marker_rms <= max_marker_rms, marker_rms, f"<= {max_marker_rms}")
                artifacts.append(artifact)

            if len(artifacts) == 2 and all(Path(item.get("output_path", "")).is_file() for item in artifacts):
                try:
                    a, _ = open_rgb(Path(artifacts[0]["output_path"]))
                    b, _ = open_rgb(Path(artifacts[1]["output_path"]))
                    cross_rms = rmsdiff(a, b)
                    evidence["export_cross_rms_diff"] = cross_rms
                    add_check(checks, "two_exports_are_distinct_images", cross_rms >= min_whole_rms, cross_rms, f">= {min_whole_rms}")
                except Exception as exc:
                    add_check(checks, "two_exports_are_distinct_images", False, str(exc), "two distinct readable exports")

            evidence["artifacts"] = artifacts
            for note in evidence["manual_trajectory_checks"]:
                add_check(checks, "manual_trajectory_check_recorded", True, note, "manual review note")

            passed = all(check["passed"] for check in checks)
            print(json.dumps({"passed": passed, "checks": checks, "evidence": evidence}, ensure_ascii=False))
            PY
            """
